    def fn(self):
        @cache('~/.bashrc')
        def fn():
            return 'test'

        return fn

    @pytest.fixture
    def key(self):
        if six.PY3:
            return 'tests.test_utils.<function TestCache.fn.<locals>.fn '
        else:
            return 'tests.test_utils.<function fn '

